-- SQL ONLINE SCHOOL ACADEMIC MANAGEMENT - FULL DATA IMPORT
-- Du lieu hoan toan gia lap, dung de hoc SQL.
-- Dung Import -> SQL script trong SQLiteOnline, hoac mo truc tiep tep .db de nhanh hon.
PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;

CREATE TABLE academic_years(year_id INTEGER PRIMARY KEY, year_name TEXT NOT NULL UNIQUE, start_date TEXT NOT NULL,end_date TEXT NOT NULL);
CREATE TABLE subjects(subject_id INTEGER PRIMARY KEY, subject_code TEXT UNIQUE NOT NULL, subject_name TEXT NOT NULL, subject_group TEXT NOT NULL);
CREATE TABLE teachers(teacher_id INTEGER PRIMARY KEY, teacher_code TEXT UNIQUE, full_name TEXT NOT NULL, gender TEXT NOT NULL, hire_date TEXT, role TEXT NOT NULL CHECK(role IN ('GIANG_DAY','BAN_TRU')), specialty_subject_id INTEGER, FOREIGN KEY(specialty_subject_id) REFERENCES subjects(subject_id));
CREATE TABLE classes(class_id INTEGER PRIMARY KEY,class_name TEXT UNIQUE NOT NULL,grade INTEGER NOT NULL CHECK(grade BETWEEN 1 AND 12),level TEXT NOT NULL, school_year_id INTEGER NOT NULL, homeroom_teacher_id INTEGER, boarding_teacher_id INTEGER, FOREIGN KEY(school_year_id) REFERENCES academic_years(year_id),FOREIGN KEY(homeroom_teacher_id) REFERENCES teachers(teacher_id),FOREIGN KEY(boarding_teacher_id) REFERENCES teachers(teacher_id));
CREATE TABLE students(student_id INTEGER PRIMARY KEY,student_code TEXT UNIQUE NOT NULL,full_name TEXT NOT NULL, gender TEXT NOT NULL, date_of_birth TEXT NOT NULL, enrollment_date TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('DANG_HOC','BAO_LUU')), class_id INTEGER NOT NULL, FOREIGN KEY(class_id) REFERENCES classes(class_id));
CREATE TABLE grade_subjects(grade INTEGER NOT NULL, subject_id INTEGER NOT NULL, subject_type TEXT NOT NULL CHECK(subject_type IN ('BAT_BUOC','LUA_CHON','TU_CHON')), PRIMARY KEY(grade,subject_id),FOREIGN KEY(subject_id) REFERENCES subjects(subject_id));
CREATE TABLE teaching_assignments(assignment_id INTEGER PRIMARY KEY,class_id INTEGER NOT NULL,subject_id INTEGER NOT NULL,teacher_id INTEGER NOT NULL,semester INTEGER NOT NULL CHECK(semester IN (1,2)), UNIQUE(class_id,subject_id,semester), FOREIGN KEY(class_id) REFERENCES classes(class_id), FOREIGN KEY(subject_id) REFERENCES subjects(subject_id), FOREIGN KEY(teacher_id) REFERENCES teachers(teacher_id));
CREATE TABLE assessments(assessment_id INTEGER PRIMARY KEY,student_id INTEGER NOT NULL,subject_id INTEGER NOT NULL,semester INTEGER NOT NULL,assessment_type TEXT NOT NULL CHECK(assessment_type IN ('THUONG_XUYEN','GIUA_KY','CUOI_KY')),score REAL CHECK(score BETWEEN 0 AND 10),result_label TEXT,exam_date TEXT, FOREIGN KEY(student_id) REFERENCES students(student_id), FOREIGN KEY(subject_id) REFERENCES subjects(subject_id));
CREATE TABLE attendance(attendance_id INTEGER PRIMARY KEY,student_id INTEGER NOT NULL,attendance_date TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('CO_MAT','VANG_CO_PHEP','VANG_KHONG_PHEP','DI_MUON')), UNIQUE(student_id,attendance_date), FOREIGN KEY(student_id) REFERENCES students(student_id));










CREATE INDEX idx_assess_student_subject ON assessments(student_id,subject_id);
CREATE INDEX idx_assign_class ON teaching_assignments(class_id);
CREATE INDEX idx_attendance_student_date ON attendance(student_id,attendance_date);
CREATE INDEX idx_students_class ON students(class_id);
CREATE VIEW vw_danh_sach_hoc_sinh AS
SELECT st.student_id, st.student_code, st.full_name, st.gender,
       st.date_of_birth, st.status, cl.class_name, cl.grade, cl.level
FROM students AS st
JOIN classes AS cl ON cl.class_id = st.class_id;
CREATE VIEW vw_si_so_lop AS
SELECT cl.class_id, cl.class_name, cl.grade, cl.level, COUNT(st.student_id) AS si_so
FROM classes AS cl
LEFT JOIN students AS st ON st.class_id = cl.class_id
GROUP BY cl.class_id, cl.class_name, cl.grade, cl.level;
CREATE VIEW vw_phan_cong_giang_day AS
SELECT a.assignment_id, cl.class_name, cl.grade, sj.subject_name,
       tc.full_name AS giao_vien, a.semester
FROM teaching_assignments AS a
JOIN classes AS cl ON cl.class_id=a.class_id
JOIN subjects AS sj ON sj.subject_id=a.subject_id
JOIN teachers AS tc ON tc.teacher_id=a.teacher_id;
CREATE VIEW vw_quan_ly_ban_tru AS
SELECT cl.class_name, cl.grade, tc.full_name AS giao_vien_ban_tru,
       tc.teacher_code
FROM classes AS cl
JOIN teachers AS tc ON tc.teacher_id=cl.boarding_teacher_id;
COMMIT;
PRAGMA foreign_keys = ON;
